// Supervised learning: simplified classification (pseudocode)
function trainClassifier(examples) {
  // examples = [{ features: [...], label: 'spam' | 'not_spam' }, ...]
  const model = initializeModel()

  for (const epoch of range(numEpochs)) {
    for (const example of examples) {
      const prediction = model.predict(example.features)
      const error = example.label - prediction
      model.adjustWeights(error)          // gradually adjust the parameters
    }
  }
  return model
}

function classify(model, newEmail) {
  const features = extractFeatures(newEmail)  // e.g. frequency of certain words
  return model.predict(features)              // 'spam' or 'not_spam'
}

// A simplified artificial neuron
function neuron(inputs, weights, bias) {
  let sum = bias
  for (let i = 0; i < inputs.length; i++) {
    sum += inputs[i] * weights[i]      // weighted combination of inputs
  }
  return activation(sum)               // non-linearity (e.g. ReLU, sigmoid)
}

function activation(x) {
  return Math.max(0, x)                // ReLU: simple but very effective in practice
}

// Forward pass through a multi-layer network
function forwardPass(input, layers) {
  let activations = input
  for (const layer of layers) {
    activations = layer.map((neuron) => neuron(activations, neuron.weights, neuron.bias))
  }
  return activations                   // final network output
}

// Text generation via sequential prediction (highly simplified pseudocode)
function generateText(prompt, model, maxTokens) {
  let tokens = tokenize(prompt)

  for (let i = 0; i < maxTokens; i++) {
    const probabilities = model.predictNextToken(tokens)  // distribution over the entire vocabulary
    const nextToken = sampleFrom(probabilities, temperature)  // weighted choice, not always the most likely
    tokens.push(nextToken)

    if (nextToken === END_TOKEN) break
  }

  return detokenize(tokens)
}
